CREATE OR REPLACE FUNCTION public.deduct_order_ingredients_on_completion()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'pg_catalog', 'public'
  AS $function$
declare
  v_claimed_order_id text;
  v_requirement record;
  v_updated_count integer;
begin
  if new.status <> 'Completed' then
    return new;
  end if;

  if tg_op = 'UPDATE' and old.status = 'Completed' then
    return new;
  end if;

  insert into public.order_inventory_deductions (order_id)
  values (new.id::text)
  on conflict (order_id) do nothing
  returning order_id into v_claimed_order_id;

  if v_claimed_order_id is null then
    return new;
  end if;

  for v_requirement in
    select recipe.ingredient_id,
           sum(recipe.quantity * ordered_item.quantity)::numeric as quantity
    from public.order_items as ordered_item
    join public.menu_item_ingredients as recipe
      on recipe.menu_item_id = ordered_item.menu_item_id
    where ordered_item.order_id = new.id
    group by recipe.ingredient_id
    order by recipe.ingredient_id
  loop
    update public.ingredients
    set current_stock = current_stock - v_requirement.quantity
    where id = v_requirement.ingredient_id
      and current_stock >= v_requirement.quantity;

    get diagnostics v_updated_count = row_count;
    if v_updated_count = 0 then
      raise exception 'Insufficient stock for ingredient %. Order % was not completed.',
        v_requirement.ingredient_id, new.order_number
        using errcode = '23514';
    end if;

    insert into public.stock_movements (ingredient_id, adjustment, reason)
    values (
      v_requirement.ingredient_id,
      -v_requirement.quantity,
      'Order ' || new.order_number || ' completed'
    );
  end loop;

  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."deduct_order_ingredients_on_completion"() FROM PUBLIC, "anon", "authenticated", "service_role";

CREATE OR REPLACE FUNCTION public.get_customer_menu()
  RETURNS TABLE (
    id            bigint,
    name          text,
    description   text,
    brand         text,
    main_category text,
    sub_category  text,
    price         numeric,
    image_url     text,
    available     integer,
    is_available  boolean,
    is_featured   boolean,
    variants      jsonb
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select
    m.id,
    m.name,
    m.description,
    m.brand,
    main_category.name,
    sub_category.name,
    m.price,
    m.image_url,
    case when coalesce(stock.has_recipe, false) and m.is_available
      then coalesce(stock.portions, 0) else 0 end::integer,
    coalesce(stock.has_recipe, false) and m.is_available and coalesce(stock.portions, 0) > 0,
    m.is_featured,
    coalesce(variants.items, '[]'::jsonb)
  from public.menu_items m
  left join public.menu_categories main_category on main_category.id = m.category_id
  left join public.menu_categories sub_category on sub_category.id = m.subcategory_id
  left join lateral (
    select
      count(*) > 0 as has_recipe,
      floor(min(i.current_stock / mi.quantity))::integer as portions
    from public.menu_item_ingredients mi
    join public.ingredients i on i.id = mi.ingredient_id
    where mi.menu_item_id = m.id
  ) stock on true
  left join lateral (
    select jsonb_agg(jsonb_build_object(
      'id', v.id,
      'variant_key', v.variant_key,
      'name', v.name,
      'price', v.price
    ) order by v.sort_order, v.id) as items
    from public.menu_item_variants v
    where v.menu_item_id = m.id
  ) variants on true
  where m.is_active
  order by m.id;
$function$;

REVOKE ALL ON FUNCTION "public"."get_customer_menu"() FROM "service_role";

CREATE OR REPLACE FUNCTION public.get_customer_order (
  p_qr_token     text,
  p_order_number text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare result jsonb;
begin
  if not public.is_valid_qr_token(p_qr_token) then raise exception 'Invalid or expired QR access'; end if;
  select jsonb_build_object('id',o.id,'orderNumber',o.order_number,'customerName',o.customer_name,
    'orderType',o.order_type,'paymentMethod',o.payment_method,'paymentReferenceNumber',o.payment_reference_number,
    'status',o.status,'notes',o.notes,'totalAmount',coalesce(sum(oi.subtotal),0),'createdAt',o.created_at,
    'items',coalesce(jsonb_agg(jsonb_build_object('menuItemId',oi.menu_item_id,'name',oi.item_name,
      'selectedVariantId',oi.selected_variant_key,'variantLabel',oi.variant_label,'price',oi.unit_price,
      'quantity',oi.quantity,'subtotal',oi.subtotal)) filter (where oi.id is not null),'[]'::jsonb))
    into result from public.orders o left join public.order_items oi on oi.order_id=o.id
    where o.order_number=p_order_number and o.source='QR Order' group by o.id;
  if result is null then raise exception 'Order not found'; end if;
  return result;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."get_customer_order"(text, text) FROM "service_role";

