CREATE OR REPLACE FUNCTION public.is_valid_qr_token (
  raw_token text
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select exists (select 1 from public.qr_access_tokens t
    where t.token_hash = encode(extensions.digest(raw_token, 'sha256'), 'hex')
      and t.is_active and (t.expires_at is null or t.expires_at > now()))
$function$;

