begin
  new.updated_at = now();
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."set_updated_at"() FROM "anon", "authenticated", "service_role";

CREATE OR REPLACE FUNCTION public.submit_customer_feedback (
  p_qr_token     text,
  p_order_number text,
  p_rating       smallint,
  p_message      text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare f public.feedback;
begin
  if not public.is_valid_qr_token(p_qr_token) then raise exception 'Invalid or expired QR access'; end if;
  if p_rating < 1 or p_rating > 5 then raise exception 'Rating must be from 1 to 5'; end if;
  insert into public.feedback(order_id,rating,message)
    select id,p_rating,trim(p_message) from public.orders
    where order_number=p_order_number and source='QR Order' and status='Completed'
    returning * into f;
  if not found then raise exception 'Feedback requires a completed QR order'; end if;
  return jsonb_build_object('id',f.id,'orderNumber',p_order_number,'rating',f.rating,
    'feedbackType',f.feedback_type,'message',f.message,'status',f.status,
    'submittedDate',f.created_at::date,'submittedTime',to_char(f.created_at,'HH12:MI AM'));
end;
$function$;

REVOKE ALL ON FUNCTION "public"."submit_customer_feedback"(text, text, smallint, text) FROM "service_role";

CREATE OR REPLACE FUNCTION public.sync_menu_availability_from_ingredient()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  linked_item record;
begin
  for linked_item in
    select menu_item_id
    from public.menu_item_ingredients
    where ingredient_id = coalesce(new.id, old.id)
  loop
    perform public.refresh_menu_item_availability(linked_item.menu_item_id);
  end loop;
  return coalesce(new, old);
end;
$function$;

REVOKE ALL ON FUNCTION "public"."sync_menu_availability_from_ingredient"() FROM PUBLIC, "anon", "authenticated", "service_role";

CREATE OR REPLACE FUNCTION public.sync_menu_availability_from_menu_item()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  perform public.refresh_menu_item_availability(new.id);
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."sync_menu_availability_from_menu_item"() FROM PUBLIC, "anon", "authenticated", "service_role";

CREATE OR REPLACE FUNCTION public.sync_menu_availability_from_recipe()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if tg_op <> 'INSERT' then
    perform public.refresh_menu_item_availability(old.menu_item_id);
  end if;
  if tg_op <> 'DELETE' then
    perform public.refresh_menu_item_availability(new.menu_item_id);
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."sync_menu_availability_from_recipe"() FROM PUBLIC, "anon", "authenticated", "service_role";

